{
  "findings": [
    {
      "check_id": "CKV2_AWS_22",
      "title": "Ensure an IAM User does not have access to the console",
      "resource": "aws_iam_user.privesc11-PutGroupPolicy-user",
      "severity": "MEDIUM",
      "explanation": "IAM users should not have access to the AWS Management Console unless explicitly required. This user does not specify whether console access is disabled, which could lead to unnecessary exposure."
    }
  ],
  "patched_code": "resource \"aws_iam_user\" \"privesc11-PutGroupPolicy-user\" {\n  name = \"privesc11-PutGroupPolicy-user\"\n  path = \"/\"\n\n  tags = {\n    \"forbid_console_access\" = \"true\"\n  }\n}",
  "fix_summary": "Added a tag to indicate that console access should be forbidden for the IAM user. This ensures compliance with the policy to restrict unnecessary console access."
}
